/// Split shard set selection.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Wiki40BSplit {
	/// `wiki40b-train` TFRecord shards.
	#[default]
	Train,
	/// `wiki40b-validation` TFRecord shards.
	Validation,
	/// `wiki40b-test` TFRecord shards.
	Test,
}

/// Load options for [`Wiki40B`][crate::text::wiki40b::Wiki40B].
#[derive(Clone, Debug)]
pub struct Wiki40BConfig {
	/// Cap decoded samples at the first `count` entries; `None` decodes
	/// the full split (GiB-scale f32 memory).
	pub count: Option<usize>,
	/// Which split shard set to decode.
	pub split: Wiki40BSplit,
	/// Cache root override. `None` resolves `OA_DATA_DIR`, then the platform
	/// cache directory; see [`data_root`](crate::pack::data_root).
	pub cache_dir: Option<PathBuf>,
}

impl Default for Wiki40BConfig {
	fn default() -> Self {
		Self {
			count: None,
			split: Wiki40BSplit::Train,
			cache_dir: None,
		}
	}
}

impl Wiki40BConfig {
	/// Construct the record with its default state.
	#[inline]
	#[must_use]
	pub fn new() -> Self {
		Self::default()
	}
}

impl super::Wiki40B {
	/// Decode the selected split and upload it on this thread's
	/// default engine.
	///
	/// # Errors
	///
	/// Returns an error when the default engine cannot be
	/// initialized, plus the errors of
	/// [`load_on`](Self::load_on).
	#[inline]
	pub fn load(config: &Wiki40BConfig) -> Result<Self> {
		Self::load_on(&Engine::current()?, config)
	}

	/// Decode the selected split and upload it on `engine`.
	///
	/// This is the [`load`](Self::load) contract evaluated on
	/// `engine` instead of this thread's default engine.
	///
	/// # Errors
	///
	/// Returns the errors of
	/// [`load_with_progress_on`](Self::load_with_progress_on).
	#[inline]
	pub fn load_on(engine: &Engine, config: &Wiki40BConfig) -> Result<Self> {
		Self::load_with_progress_on(engine, config, &mut |_| true)
	}

	/// [`load`](Self::load) with a fetch progress callback.
	///
	/// # Errors
	///
	/// Returns an error when the default engine cannot be
	/// initialized, plus the errors of
	/// [`load_with_progress_on`](Self::load_with_progress_on).
	#[inline]
	pub fn load_with_progress(
		config: &Wiki40BConfig,
		progress: &mut impl FnMut(FetchProgress) -> bool,
	) -> Result<Self> {
		Self::load_with_progress_on(&Engine::current()?, config, progress)
	}
}
